import { randomUUID } from "node:crypto";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";

/** originals/: uploads exactly as received (private). display/: metadata-free copies (served). */
export type StorageArea = "originals" | "display";
export type StoredExtension = "jpg" | "png";

/**
 * Stores uploaded images. Keys are generated by the server (random UUIDs); the client's file
 * name is never used, so no path can be influenced by a user.
 */
export interface FileStorage {
  save(area: StorageArea, data: Buffer, extension: StoredExtension): Promise<string>;
  read(key: string): Promise<Buffer>;
  /** Deletes a file; missing files are ignored. */
  delete(key: string): Promise<void>;
}

const KEY_PATTERN = /^(originals|display)\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png)$/;

export function isValidStorageKey(key: string): boolean {
  return KEY_PATTERN.test(key);
}

/** Local-disk storage under `rootDir` (UPLOAD_DIR). The folder must never be served statically. */
export async function createLocalFileStorage(rootDir: string): Promise<FileStorage> {
  await Promise.all([
    mkdir(join(rootDir, "originals"), { recursive: true, mode: 0o700 }),
    mkdir(join(rootDir, "display"), { recursive: true, mode: 0o700 }),
  ]);

  const pathFor = (key: string): string => {
    // Defence in depth: keys come from our database, but never build a path from anything else.
    if (!isValidStorageKey(key)) {
      throw new Error("Invalid storage key");
    }
    return join(rootDir, key);
  };

  return {
    save: async (area, data, extension) => {
      const key = `${area}/${randomUUID()}.${extension}`;
      // "wx": fail instead of overwriting; 0600: readable only by the server's user.
      await writeFile(pathFor(key), data, { flag: "wx", mode: 0o600 });
      return key;
    },
    read: (key) => readFile(pathFor(key)),
    delete: (key) => rm(pathFor(key), { force: true }),
  };
}
